record.field:
{
                "type": "object",
                "properties": {
                    "model": {"type": "string", "description": "Odoo model technical name (e.g. sale.order, res.partner)"},
                    "domain": {"type": "array", "description": "Odoo domain list (e.g. [['state', '=', 'sale']])"},
                    "fields": {"type": "array", "items": {"type": "string"}, "description": "List of field names to read"},
                    "limit": {"type": "integer", "description": "Maximum number of records to return (default: 20)"}
                },
                "required": ["model"]
            }

{
                "type": "object",
                "properties": {
                    "model": {"type": "string", "description": "Odoo model technical name"},
                    "values": {"type": "object", "description": "Dictionary of field values to set"}
                },
                "required": ["model", "values"]
            }

{
                "type": "object",
                "properties": {
                    "model": {"type": "string", "description": "Odoo model technical name"},
                    "ids": {"type": "array", "items": {"type": "integer"}, "description": "List of record IDs to update"},
                    "values": {"type": "object", "description": "Dictionary of field values to write"}
                },
                "required": ["model", "ids", "values"]
            }

{
                "type": "object",
                "properties": {
                    "model": {"type": "string", "description": "Odoo model technical name"},
                    "ids": {"type": "array", "items": {"type": "integer"}, "description": "List of record IDs to delete"}
                },
                "required": ["model", "ids"]
            }

{
                "type": "object",
                "properties": {
                    "model": {"type": "string", "description": "Odoo model technical name"},
                    "question": {"type": "string", "description": "Analysis task or question to answer"},
                    "domain": {"type": "array", "description": "Odoo domain list filter"},
                    "fields": {"type": "array", "items": {"type": "string"}, "description": "Fields to inspect"},
                    "limit": {"type": "integer", "description": "Record limit"}
                },
                "required": ["model", "question"]
            }

{
                "type": "object",
                "properties": {
                    "page_id": {"type": "integer", "description": "Target website page ID"},
                    "url": {"type": "string", "description": "Website page URL (e.g. '/services')"},
                    "meta_title": {"type": "string", "description": "Optimized search engine title"},
                    "meta_description": {"type": "string", "description": "Compelling search engine description snippet (150-160 chars)"},
                    "keywords": {"type": "string", "description": "Comma-separated target SEO keywords"}
                }
            }

{
                "type": "object",
                "properties": {
                    "snippet_type": {"type": "string", "enum": ["hero", "features", "faqs", "cta"], "description": "Type of snippet block to generate"},
                    "title": {"type": "string", "description": "Main heading for the section"},
                    "subtitle": {"type": "string", "description": "Subtitle or intro paragraph"},
                    "items": {"type": "array", "description": "List of cards/items with title, description, and optional icon or question/answer"},
                    "cta_text": {"type": "string", "description": "Call-to-action button text"},
                    "cta_url": {"type": "string", "description": "Call-to-action target link URL"}
                },
                "required": ["snippet_type", "title"]
            }

{
                "type": "object",
                "properties": {
                    "page_id": {"type": "integer", "description": "Target website page ID"},
                    "url": {"type": "string", "description": "Target website URL path"},
                    "snippet_html": {"type": "string", "description": "Complete valid QWeb / HTML snippet to inject"},
                    "action": {"type": "string", "enum": ["append", "prepend"], "description": "Insertion mode (default: append)"}
                },
                "required": ["snippet_html"]
            }

{
                "type": "object",
                "properties": {
                    "product_tmpl_id": {"type": "integer", "description": "Target product.template record ID"},
                    "selling_points": {"type": "array", "items": {"type": "string"}, "description": "Key value propositions & highlights"},
                    "faq_items": {"type": "array", "description": "List of FAQ objects with question and answer strings"},
                    "specs": {"type": "object", "description": "Technical specifications key-value dictionary"}
                },
                "required": ["product_tmpl_id"]
            }
